// Monta a mensagem do WhatsApp
const meetingId = $('3. Prepare Metadata').first().json.meeting_id;
const summary = $('Aggregate').first().json.summary;
// O que NASCEU vem do frontend (que já comparou com as tarefas existentes);
// o que já existia virou "falada de novo" no card antigo e entra numa linha só.
let inc = null;
try { inc = $('11b. Incorporar tarefas').first().json; } catch (e) { inc = null; }
const items = inc && Array.isArray(inc.criadas)
  ? inc.criadas
  : $('Aggregate').all().map(i => i.json).filter(j => !j.no_actions);
const jaExistiam = inc && Array.isArray(inc.juntadas) ? inc.juntadas.length : 0;

const minhas = items.filter(i => i.owner === 'eu');
const delegadas = items.filter(i => i.owner !== 'eu');
const formatPrazo = (p) => {
  if (!p) return '';
  try {
    const d = new Date(p);
    return ' _(até ' + d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }) + ')_';
  } catch { return ''; }
};
const emojiPrio = { urgente: '🔴', alta: '🟠', media: '🟡', baixa: '⚪' };

let msg = '🎙️ *Reunião processada*\n\n';
msg += '_' + summary + '_\n\n';

if (minhas.length) {
  msg += '✅ *Minhas ações* (' + minhas.length + ')\n';
  minhas.forEach(t => {
    msg += (emojiPrio[t.prioridade] || '🟡') + ' ' + t.titulo + formatPrazo(t.prazo) + '\n';
  });
  msg += '\n';
}

if (delegadas.length) {
  msg += '👥 *Combinei com outros* (' + delegadas.length + ')\n';
  delegadas.forEach(t => {
    msg += (emojiPrio[t.prioridade] || '🟡') + ' *' + t.owner + ':* ' + t.titulo + formatPrazo(t.prazo) + '\n';
  });
  msg += '\n';
}

if (jaExistiam) {
  msg += '♻️ Já existiam ' + jaExistiam + ', anotei nos cards\n\n';
}

if (!minhas.length && !delegadas.length && !jaExistiam) {
  msg += '_(nenhuma ação concreta extraída desta reunião)_\n';
}

const frontendUrl = 'https://srv2007125.hstgr.cloud';
msg += '🔗 ' + frontendUrl + '/reunioes/' + meetingId;


// Aviso de áudio longo aguardando segmentação
const needsSeg = $('12c. Mark Needs Segmentation').first().json.needs_segmentation;
const dur = $('12c. Mark Needs Segmentation').first().json.duration_seconds;
if (needsSeg) {
  msg += '\n\n🎙️ Áudio longo (' + (dur/3600).toFixed(1) + 'h) — revisar segmentação:\n';
  msg += frontendUrl + '/reunioes/' + meetingId + '/segmentar';
}
return [{ json: { text: msg, meeting_id: meetingId, n_tarefas: items.length } }];

// Marca se a meeting precisa ser revisada pra segmentação manual.
// Limite: > 60min (3600s). Não bloqueia o fluxo se duração ausente.
const meta = $('3. Prepare Metadata').first().json;
const duration = meta.duration_seconds_local || 0;
const needs = duration > 3600;
return [{
  json: {
    needs_segmentation: needs,
    meeting_id: meta.meeting_id,
    duration_seconds: duration
  }
}];

// coleta as N saídas do GPT, parseia as actions de cada run, monta o prompt do juiz
const items = $input.all();
function parse(raw) {
  let p;
  if (raw.message && raw.message.content) p = typeof raw.message.content === 'string' ? JSON.parse(raw.message.content) : raw.message.content;
  else if (raw.content) p = typeof raw.content === 'string' ? JSON.parse(raw.content) : raw.content;
  else if (raw.text) p = typeof raw.text === 'string' ? JSON.parse(raw.text) : raw.text;
  else p = raw;
  return p || {};
}
const parsed = items.map(it => parse(it.json));
const runs = parsed.map(p => Array.isArray(p.actions) ? p.actions : []);
const __ctx = $('Build Distiller Input').first().json;
let summary = __ctx.summary || '', executive_summary = __ctx.executive_summary || null;
const lines = [];
runs.forEach((acts, ri) => {
  lines.push('EXECUÇÃO ' + (ri + 1) + ':');
  acts.forEach((a, ii) => lines.push('  [' + (ri + 1) + '.' + ii + '] ' + (a.titulo || '') + ' (owner=' + (a.owner || '') + ')'));
});
const judgePrompt =
  'Abaixo, tarefas extraídas da MESMA reunião em várias execuções do mesmo modelo. ' +
  'Diferenças de REDAÇÃO são esperadas — IGNORE. Agrupe os itens que são a MESMA tarefa subjacente ' +
  '(o MESMO ENTREGÁVEL/OBJETIVO). IGNORE diferenças de redação E de dono (execuções discordam de quem faz — o dono é resolvido depois por maioria): agrupe itens do mesmo entregável AINDA QUE os donos difiram. Itens distintos NÃO devem ser juntados só por tema parecido. ' +
  'Cada item pertence a exatamente um grupo. Para cada grupo dê "canonical" — uma FRASE DIRETA E COMPLETA no estilo do próprio título (verbo no infinitivo + o ENTREGÁVEL CONCRETO), escolhendo/unindo a redação MAIS COMPLETA entre os membros; NÃO encurte para rótulo genérico ' +
  'e "refs" (lista de "R.I" dos membros). Retorne JSON: {"grupos":[{"canonical":"...","refs":["1.0","2.3"]}]}\n\n' +
  lines.join('\n');
return [{ json: { judgePrompt: judgePrompt, runs: runs, summary: summary, executive_summary: executive_summary, raw_ai_response: JSON.stringify({ summary: summary, executive_summary: executive_summary }) } }];

// AGREGA por maioria (self-consistency N=3) + enforcement determinístico
const __slug=(x)=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const __dono=__slug((()=>{try{return $('7f. SELECT pessoas').first().json.dono_nome}catch(e){return ''}})());
const __donoPrimeiro=__dono.split(' ')[0]||'';
function normOwner(o){const s=(o==null?'':String(o)).trim(); if(!s)return 'eu'; if(/^eu$/i.test(s))return 'eu'; const k=__slug(s); if(__dono && (k===__dono || (__donoPrimeiro.length>2 && k===__donoPrimeiro)))return 'eu'; if(/^speaker\b/i.test(s))return '?'; return s;}
function coerceAcao(owner,acao){const o=normOwner(owner); if(o==='eu')return 'executar'; return ['cobrar','aguardar'].includes(acao)?acao:'cobrar';}
function cleanPrazo(t){if(t==null)return null; const s=String(t).trim(); if(!s)return null; const re=/(hoje|amanh[ãa]|ontem|segunda|ter[çc]a|quarta|quinta|sexta|s[áa]bado|domingo|semana|mês|meses|que vem|daqui a|fim de semana|feriado|manh[ãa]|tarde|noite|madrugada|daily|janeiro|fevereiro|mar[çc]o|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro|\d{1,2}\s*\/\s*\d{1,2}|dia\s+\d{1,2}|\d{1,2}\s*h\b|\d{1,2}:\d{2})/i; return re.test(s)?s:null;}
function mode(vals){const c={}; let best=null,bn=0; for(const v of vals){ if(v==null||v==='')continue; const k=(typeof v==='object')?JSON.stringify(v):String(v); c[k]=(c[k]||0)+1; if(c[k]>bn){bn=c[k]; best=v;} } return best;}

const ctx = $('Build Judge Prompt').first().json;
const runs = ctx.runs || [];
const N = runs.length || 3;
const maj = Math.floor(N/2)+1;
const jr = $input.first().json;
let grupos=[];
try{ let p = (jr.message && jr.message.content) ? jr.message.content : (jr.content||jr.text||jr); p = (typeof p==='string')?JSON.parse(p):p; grupos = p.grupos||[]; }catch(e){ grupos=[]; }

const meetingId = $('3. Prepare Metadata').first().json.meeting_id;
const rawJson = ctx.raw_ai_response || '{}';
const summary = ctx.summary || '';

const out=[];
for(const g of grupos){
  const refs=[]; const runset=new Set();
  for(const ref of (g.refs||[])){
    const m=String(ref).split('.'); const ri=parseInt(m[0],10)-1, ii=parseInt(m[1],10);
    if(runs[ri] && runs[ri][ii]){ refs.push(runs[ri][ii]); runset.add(ri); }
  }
  if(!refs.length) continue;
  const cov=runset.size;
  let rep=refs[0]; for(const r of refs){ if(String(r.descricao||'').length>String(rep.descricao||'').length) rep=r; }
  const owner=normOwner(mode(refs.map(r=>r.owner)));
  const acao=coerceAcao(owner, mode(refs.map(r=>r.acao)));
  let pessoas=[]; for(const r of refs){ for(const pp of (r.pessoas_envolvidas||[])){ if(!pessoas.some(x=>String(x).trim().toLowerCase()===String(pp).trim().toLowerCase())) pessoas.push(pp);} }
  if(owner!=='eu'&&owner!=='?'&&!pessoas.some(x=>String(x).trim().toLowerCase()===owner.toLowerCase())) pessoas.unshift(owner);
  pessoas=pessoas.filter(p=>!/^speaker\b/i.test(String(p).trim()));
  const prio=mode(refs.map(r=>r.prioridade));
  out.push({
    titulo: g.canonical || rep.titulo || '(sem título)',
    descricao: rep.descricao || '',
    owner: owner, acao: acao,
    prazo: (function(pt){var iso=mode(refs.map(r=>r.prazo_iso));if(!pt||iso==null)return null;var mm=String(iso).match(/(\d{4})-(\d{2})-(\d{2})/);return mm?mm[1]+'-'+mm[2]+'-'+mm[3]+'T23:59:00-03:00':null;})(cleanPrazo(mode(refs.map(r=>r.prazo_text)))),
    prazo_text: cleanPrazo(mode(refs.map(r=>r.prazo_text))),
    prioridade: ['baixa','media','alta','urgente'].includes(prio)?prio:'media',
    evidencia: rep.evidencia || '',
    area_raw: mode(refs.map(r=>r.area)) || null,
    pessoas_raw: JSON.stringify(pessoas),
    precisa_revisao: cov < maj
  });
}
// dedup determinístico: colapsa tarefas de título normalizado idêntico (rede de segurança)
function __normT(t){return String(t||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();}
{const __seen={};const __dd=[];for(const a of out){const k=__normT(a.titulo);if(__seen[k]){const e=__seen[k];try{const pa=JSON.parse(e.pessoas_raw||'[]'),pb=JSON.parse(a.pessoas_raw||'[]');for(const x of pb){if(!pa.some(y=>String(y).toLowerCase()===String(x).toLowerCase()))pa.push(x);}e.pessoas_raw=JSON.stringify(pa);}catch(_e){}if(String(a.descricao||'').length>String(e.descricao||'').length)e.descricao=a.descricao;if(!e.prazo&&a.prazo){e.prazo=a.prazo;e.prazo_text=a.prazo_text;}e.precisa_revisao=e.precisa_revisao&&a.precisa_revisao;}else{__seen[k]=a;__dd.push(a);}}out.length=0;out.push(...__dd);}
if(!out.length){
  return [{ json:{ meeting_id:meetingId, summary:summary, raw_ai_response:rawJson, no_actions:true } }];
}
return out.map((a,i)=>({ json: Object.assign({ meeting_id:meetingId, summary:summary, raw_ai_response:rawJson, idx:i, total:out.length }, a) }));

// Junta o relatório do Stage A + texto rotulado + (feedback) pro distiller.
function parse(raw){ let p; if(raw.message&&raw.message.content) p= typeof raw.message.content==='string'?JSON.parse(raw.message.content):raw.message.content; else if(raw.content) p=typeof raw.content==='string'?JSON.parse(raw.content):raw.content; else p=raw; return p||{}; }
const sa = parse($input.first().json);
const blt = $('7e. Build Labeled Text').first().json;
const fb = { block: '' };
let data_reuniao='';try{const __ra=$('7e. Build Labeled Text').first().json.recorded_at;if(__ra){data_reuniao=new Date(__ra).toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric',timeZone:'America/Sao_Paulo'});}}catch(e){}
return [{ json: {
  data_reuniao,
  summary: sa.summary || '',
  executive_summary: sa.executive_summary || '',
  labeled_text: blt.labeled_text || '',
  feedback_block: (fb && fb.block) || '',
} }];

// Junta as tarefas agregadas numa entrega só. O frontend compara com as que
// já existem antes de gravar: repetida vira "falada de novo" no card antigo.
const aggs = $('Aggregate').all().map(i => i.json).filter(j => !j.no_actions);
const meta = $('3. Prepare Metadata').first().json;
const tarefas = aggs.map(j => ({
  titulo: j.titulo, descricao: j.descricao, owner: j.owner, acao: j.acao,
  prazo: j.prazo, prazo_text: j.prazo_text, prioridade: j.prioridade,
  evidencia: j.evidencia, area_raw: j.area_raw, pessoas_raw: j.pessoas_raw,
  precisa_revisao: j.precisa_revisao,
}));
return [{ json: { user_id: meta.user_id, meeting_id: meta.meeting_id, reprocessar: false, tarefas } }];

// Junta o que o relatório precisa (transcrição, data e pessoas) para o fluxo "Equipe - Acoes - Relatorio Luna"
let recorded_at = null; try { recorded_at = $('7e. Build Labeled Text').first().json.recorded_at || null; } catch (e) {}
let pessoas = []; try { pessoas = $('7f. SELECT pessoas').all().map(p => ({ nome: p.json.nome, aliases: p.json.aliases || [] })); } catch (e) {}
let dono_nome = ''; try { dono_nome = String($('7f. SELECT pessoas').first().json.dono_nome || ''); } catch (e) {}
return [{ json: { dono_nome, labeled_text: String($('7e. Build Labeled Text').first().json.labeled_text || ''), recorded_at, pessoas } }];

// Adapta dados do SELECT pra ficar compatível com nós copiados do principal
// (que referenciam $('3. Prepare Metadata').first().json.*).
const meeting = $input.first().json;
if (!meeting || !meeting.id) {
  throw new Error('meeting não encontrada: ' + JSON.stringify(meeting).slice(0, 200));
}
return [{
  json: {
    meeting_id: meeting.id,
    user_id: meeting.user_id,
    transcription: meeting.transcription || '',
    duration_seconds_local: meeting.duration_seconds || 0,
    recorded_at: meeting.recorded_at,
    source: meeting.source || 'segmented',
    meeting_type: meeting.meeting_type || 'desconhecido',
    segments_local: meeting.segments || []
  }
}];

// Usa transcrição + segments já prontos do Mac.
// Formato compatível: { text, duration, language, segments }.
const meta = $('3. Prepare Metadata').first().json;
return [{
  json: {
    text: meta.transcription || '',
    duration: meta.duration_seconds_local || 0,
    language: 'pt',
    segments: meta.segments_local || [],
  }
}];

