  });
}
// dedup determinístico: colapsa tarefas de título normalizado idêntico (rede de segurança)
function __normT(t){return String(t||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();}
{const __seen={};const __dd=[];for(const a of out){const k=__normT(a.titulo);if(__seen[k]){const e=__seen[k];try{const pa=JSON.parse(e.pessoas_raw||'[]'),pb=JSON.parse(a.pessoas_raw||'[]');for(const x of pb){if(!pa.some(y=>String(y).toLowerCase()===String(x).toLowerCase()))pa.push(x);}e.pessoas_raw=JSON.stringify(pa);}catch(_e){}if(String(a.descricao||'').length>String(e.descricao||'').length)e.descricao=a.descricao;if(!e.prazo&&a.prazo){e.prazo=a.prazo;e.prazo_text=a.prazo_text;}e.precisa_revisao=e.precisa_revisao&&a.precisa_revisao;}else{__seen[k]=a;__dd.push(a);}}out.length=0;out.push(...__dd);}
if(!out.length){
  return [{ json:{ meeting_id:meetingId, summary:summary, raw_ai_response:rawJson, no_actions:true } }];
}
return out.map((a,i)=>({ json: Object.assign({ meeting_id:meetingId, summary:summary, raw_ai_response:rawJson, idx:i, total:out.length }, a) }));

// Junta o relatório do Stage A + texto rotulado + (feedback) pro distiller.
function parse(raw){ let p; if(raw.message&&raw.message.content) p= typeof raw.message.content==='string'?JSON.parse(raw.message.content):raw.message.content; else if(raw.content) p=typeof raw.content==='string'?JSON.parse(raw.content):raw.content; else p=raw; return p||{}; }
const sa = parse($input.first().json);
const blt = $('Build Labeled Text').first().json;
const fb = { block: '' };
let data_reuniao='';try{const __ra=$('Build Labeled Text').first().json.recorded_at;if(__ra){data_reuniao=new Date(__ra).toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric',timeZone:'America/Sao_Paulo'});}}catch(e){}
