// Junta o que o relatório precisa (transcrição, data e pessoas) para o fluxo "Equipe - Acoes - Relatorio Luna"
let recorded_at = null; try { recorded_at = $('Build Labeled Text').first().json.recorded_at || null; } catch (e) {}
